// Deterministic patient-facing messages for every critical fact (offer, confirmation, expiry...).
// Critical facts are never generated by the LLM.

export const firstName = (full: string) => full.trim().split(/\s+/)[0] ?? 'there';
export const maskedName = (full: string) => {
  const p = full.trim().split(/\s+/);
  return p.length > 1 ? `${p[0]} ${p[p.length - 1][0]}.` : p[0];
};

export const T = {
  // `shared`: the slot may be on offer to other patients too, so the message says so (first to confirm gets it).
  offer: (name: string, treatment: string, slot: string, clinic: string, ttlMinutes: number, shared = false) =>
    `Hi ${name}! This is ${clinic}. A ${treatment.toLowerCase()} appointment is available ${slot}. Would you like to book it? Please reply yes or no within ${ttlMinutes} minutes.`
    + (shared ? ` We are offering it to a few patients on our waiting list, and it goes to the first one who confirms.` : ''),
  confirmation: (name: string, treatment: string, slot: string) => `You're all set! Your ${treatment.toLowerCase()} is confirmed for ${slot}. See you then 😊`,
  declinedAck: (name: string) => `No problem, thanks for letting us know. You'll keep your place on the waiting list.`,
  alreadyBookedAck: (name: string) => `Thanks for letting us know. I've taken you off the waiting list for this treatment.`,
  optOutAck: () => `Understood. We won't send you any more appointment offers by WhatsApp.`,
  expired: () => `This appointment offer has now expired. You'll keep your place on our waiting list.`,
  lateReply: () => `Sorry, that appointment offer is no longer available. You'll keep your place on our waiting list.`,
  slotTaken: () => `Sorry, that appointment has just been booked by another patient, so it is no longer available. You'll keep your place on our waiting list.`,
  slotUnavailable: () => `Sorry, that appointment was taken just before I could book it, so nothing has been booked. You'll keep your place on our waiting list.`,
  bookingFailed: (phone: string) => `Sorry, I couldn't complete this booking automatically, so it is not booked yet. Please call the clinic on ${phone} if you'd still like it.`,
  clinical: (phone: string) =>
    `I'm sorry to hear that. I can't give medical advice over WhatsApp. Please call the clinic on ${phone}, or call your local emergency number if it is severe or urgent.`,
  humanNotified: () => `I've passed your message to our clinic team, who will get back to you.`,
  humanNotConfigured: (phone: string) => `I can't arrange that here, sorry. Please call the clinic on ${phone} and the team will help you.`,
};
